{"function":"() => {
function parse(c){const m=c.match(/[\d.]+/g);return m?m.map(Number):null}
function lum([r,g,b]){return [r,g,b].map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)}).reduce((a,v,i)=>a+v*[0.2126,0.7152,0.0722][i],0)}
function bg(el){while(el){const c=getComputedStyle(el).backgroundColor;const p=parse(c);if(p&&(p.length<4||p[3]>0))return p;el=el.parentElement}return [255,255,255]}
const out=[];
document.querySelectorAll('#root *').forEach(el=>{
 const t=[...el.childNodes].filter(n=>n.nodeType===3&&n.textContent.trim()).map(n=>n.textContent.trim()).join(' ');
 const isPh = (el.tagName==='INPUT'||el.tagName==='TEXTAREA');
 if(!t && !isPh) return;
 const cs=getComputedStyle(el); const r=el.getBoundingClientRect(); if(r.width===0) return;
 const fg=parse(cs.color); const b=bg(el);
 const L1=lum(fg.slice(0,3)),L2=lum(b.slice(0,3)); const cr=(Math.max(L1,L2)+.05)/(Math.min(L1,L2)+.05);
 let ph=null; if(isPh&&el.placeholder){const pc=getComputedStyle(el,'::placeholder'); const pf=parse(pc.color); const Lp=lum(pf.slice(0,3)); ph=[pc.color,((Math.max(Lp,L2)+.05)/(Math.min(Lp,L2)+.05)).toFixed(2), pc.opacity]}
 out.push([el.tagName+'.'+el.className, (t||el.id).slice(0,30), cs.color, 'bg'+b.join(','), cr.toFixed(2), cs.fontSize, cs.fontWeight, cs.opacity, ph]);
});
return out.map(x=>x.join(' | ')).join('\n')}"}

